const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
let n;
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 1) {
    n = lines[0] - 0;
  }

  if (n && lines.length === n + 1) {
    const wos = lines.slice(1).map((line) => line.split(" ").map(Number));
    console.log(getResult(n, wos));
    lines.length = 0;
  }
});

/**
 * @param {*} n 工单数量
 * @param {*} wos 工单的 [SLA, 积分]
 * @returns 可以获得的最大积分
 */
function getResult(n, wos) {
  // 按照SLA截止时间升序
  wos.sort((a, b) => a[0] - b[0]);

  const pq = new PriorityQueue((a, b) => a - b);

  let curTime = 0;
  let ans = 0;

  for (let wo of wos) {
    const [endTime, score] = wo;

    if (endTime >= curTime + 1) {
      pq.offer(score);
      ans += score;
      curTime++;
    } else {
      if (pq.size() == 0) {
        continue;
      }

      const min_score = pq.peek();
      if (score > min_score) {
        pq.poll();
        pq.offer(score);
        ans += score - min_score;
      }
    }
  }

  return ans;
}

// 基于堆实现优先队列
class PriorityQueue {
  constructor(cpr) {
    this.queue = [];
    this.cpr = cpr;
  }

  swap(a, b) {
    const tmp = this.queue[a];
    this.queue[a] = this.queue[b];
    this.queue[b] = tmp;
  }

  // 上浮
  swim() {
    let c = this.queue.length - 1;

    while (c >= 1) {
      const f = Math.floor((c - 1) / 2);

      if (this.cpr(this.queue[c], this.queue[f]) < 0) {
        this.swap(c, f);
        c = f;
      } else {
        break;
      }
    }
  }

  // 入队
  offer(val) {
    this.queue.push(val);
    this.swim();
  }

  // 下沉
  sink() {
    let f = 0;

    while (true) {
      let c1 = 2 * f + 1;
      let c2 = c1 + 1;

      let c;
      let val1 = this.queue[c1];
      let val2 = this.queue[c2];
      if (val1 && val2) {
        c = this.cpr(val1, val2) < 0 ? c1 : c2;
      } else if (val1 && !val2) {
        c = c1;
      } else if (!val1 && val2) {
        c = c2;
      } else {
        break;
      }

      if (this.cpr(this.queue[c], this.queue[f]) < 0) {
        this.swap(c, f);
        f = c;
      } else {
        break;
      }
    }
  }

  // 出队
  poll() {
    this.swap(0, this.queue.length - 1);
    const res = this.queue.pop();
    this.sink();
    return res;
  }

  peek() {
    return this.queue[0];
  }

  size() {
    return this.queue.length;
  }
}

